#!/usr/bin/env python3
"""Jewellery-only launch shell. No invented products or specifications."""
from pathlib import Path
from html import escape as esc
import json

ROOT=Path(__file__).resolve().parent.parent
CATEGORIES=[('necklaces','Necklaces','项链'),('bracelets','Bracelets','手链'),('rings','Rings','戒指'),('earrings','Earrings','耳环'),('pendants','Pendants','吊坠')]
def write(path,value):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value,encoding='utf-8')
def t(en,zh,tag='span',attrs=''):
    return f'<{tag} data-en="{esc(en,quote=True)}" data-zh="{esc(zh,quote=True)}" {attrs}>{esc(en)}</{tag}>'
def icon(name):
    shapes={'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>','bag':'<path d="M5 7h14l1 14H4L5 7Zm4 0V5a3 3 0 0 1 6 0v2"/>','menu':'<path d="M3 6h18M3 12h18M3 18h18"/>','arrow':'<path d="M4 12h15m-5-5 5 5-5 5"/>','close':'<path d="m5 5 14 14M5 19 19 5"/>'}
    return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">{shapes[name]}</svg>'
def nav(selected=''):
    links=[('jewellery','All jewellery','全部首饰')]+CATEGORIES
    return ''.join(f'<a href="/collections/{slug}/" {"aria-current=page" if slug==selected else ""}>{t(en,zh)}</a>' for slug,en,zh in links)
def button(href,en,zh,secondary=False):
    return f'<a class="button {"secondary" if secondary else ""}" href="{href}">{t(en,zh)}{icon("arrow")}</a>'
def shell(title,zh_title,body,page='other',selected=''):
    return f'''<!doctype html>
<html lang="en-GB" dir="ltr" data-title-en="{esc(title,quote=True)} | NOVA WELL" data-title-zh="{esc(zh_title,quote=True)} | NOVA WELL"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="NOVA WELL jewellery. A new collection of necklaces, bracelets, rings, earrings and pendants is taking shape."><meta name="theme-color" content="#f6f4ef"><title>{esc(title)} | NOVA WELL</title><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/jewellery.css"><script src="/assets/catalog.js" defer></script><script src="/assets/cart.js" defer></script><script src="/assets/jewellery.js" defer></script><script src="/assets/catalogue-ui.js" defer></script></head>
<body data-page="{page}"><a class="skip" href="#main">{t('Skip to content','跳至正文')}</a><div class="announcement">{t('A new jewellery collection is taking shape.','全新首饰系列，正在筹备。')}</div>
<header class="site-header"><div class="masthead wrap"><button class="icon-button mobile-menu" data-open="menuDialog" aria-label="Open menu">{icon('menu')}</button><a class="wordmark" href="/" aria-label="NOVA WELL home">NOVA WELL</a><div class="desktop-note">{t('JEWELLERY. EVERY DAY.','首饰，融入日常。')}</div><div class="header-actions"><button class="icon-button" data-open="searchDialog" aria-label="Search">{icon('search')}</button><button id="language" class="language" aria-label="Change language">中文</button><button class="icon-button bag-button" data-open="bagDialog" aria-label="Open bag">{icon('bag')}<span class="bag-count" aria-hidden="true">0</span></button></div></div><nav class="desktop-nav wrap" aria-label="Main navigation">{nav(selected)}</nav></header>
<main id="main" tabindex="-1">{body}</main>
<footer class="site-footer"><div class="footer-top wrap"><div class="footer-brand"><a class="wordmark" href="/">NOVA WELL</a><p>{t('Considered forms. Everyday expression.','简洁形态，日常表达。')}</p><p class="small">{t('Our first jewellery collection is in preparation.','首个首饰系列正在筹备中。')}</p></div><div><h2>{t('Discover','探索')}</h2><a href="/collections/jewellery/">{t('All jewellery','全部首饰')}</a><a href="/pages/about/">{t('Our perspective','品牌理念')}</a><a href="/pages/materials-care/">{t('Materials & care','材质与护理')}</a><a href="/pages/size-guide/">{t('Size guide','尺寸指南')}</a></div><div><h2>{t('Client care','客户服务')}</h2><a href="/pages/shipping/">{t('Shipping & delivery','配送说明')}</a><a href="/pages/returns/">{t('Returns','退货说明')}</a><a href="/pages/order-status/">{t('Order status','订单查询')}</a><a href="/pages/contact/">{t('Contact','联系我们')}</a></div><div><h2>{t('Stay close','保持关注')}</h2><p>{t('The next chapter, in the details.','下一篇章，藏在细节里。')}</p><a class="footer-link" href="/pages/updates/">{t('Collection updates','系列动态')} {icon('arrow')}</a><button class="region-button" data-open="regionDialog"><span id="regionLabel">United Kingdom · GBP</span><span aria-hidden="true">⌄</span></button></div></div><div class="footer-bottom wrap"><span>© 2026 NOVA WELL</span><div><a href="/pages/privacy/">{t('Privacy','隐私说明')}</a><a href="/pages/terms/">{t('Terms','使用条款')}</a></div><span>{t('Collection in preparation','系列筹备中')}</span></div></footer>
<dialog id="menuDialog" class="drawer menu-dialog" aria-labelledby="menuTitle"><div class="dialog-head"><h2 id="menuTitle">{t('Explore jewellery','探索首饰')}</h2><button data-close aria-label="Close menu">{icon('close')}</button></div><nav aria-label="Mobile navigation">{nav(selected)}</nav><a class="menu-about" href="/pages/about/">{t('Our perspective','品牌理念')}{icon('arrow')}</a></dialog>
<dialog id="searchDialog" class="search-dialog" aria-labelledby="searchTitle"><div class="dialog-head"><h2 id="searchTitle">{t('Find your everyday piece.','寻找你的日常首饰。')}</h2><button data-close aria-label="Close search">{icon('close')}</button></div><form class="search-form" data-search-form><label for="searchInput">{t('Search jewellery','搜索首饰')}</label><div class="search-input-row"><input id="searchInput" name="q" type="search" maxlength="120" autocomplete="off" placeholder="Necklaces, rings, everyday details…"><button class="icon-button" type="submit" aria-label="Search">{icon('search')}</button></div></form><div class="search-empty" role="status">{t('Search by model number, category or material.','输入型号、分类或材质，查找目录商品。')}</div><div class="search-categories">{nav()}</div></dialog>
<dialog id="bagDialog" class="drawer bag-dialog" aria-labelledby="bagTitle"><div class="dialog-head"><h2 id="bagTitle">{t('Your bag','你的购物袋')} <span class="small">(0)</span></h2><button data-close aria-label="Close bag">{icon('close')}</button></div><div class="empty-bag"><svg viewBox="0 0 80 90" aria-hidden="true"><path d="M18 29h44l4 48H14l4-48Zm12 0V20a10 10 0 0 1 20 0v9"/></svg><h3>{t('A little space for something considered.','为心仪之物，留一点空间。')}</h3><p>{t('Your bag is empty. Our first jewellery collection is coming together.','购物袋还是空的，首个首饰系列正在筹备中。')}</p>{button('/collections/jewellery/','Explore jewellery','探索首饰')}</div><p class="bag-note">{t('Shopping will open with our first verified collection.','首批商品资料确认后，将开放购买。')}</p></dialog>
<dialog id="regionDialog" class="region-dialog" aria-labelledby="regionTitle"><div class="dialog-head"><h2 id="regionTitle">{t('Your region','你的地区')}</h2><button data-close aria-label="Close region selector">{icon('close')}</button></div><p>{t('Choose your browsing region. Delivery availability will be confirmed before ordering opens.','选择浏览地区。开放订单前将确认可配送范围。')}</p><label for="regionSelect">{t('Region & currency','地区与货币')}</label><select id="regionSelect"><option value="GB">United Kingdom · GBP</option><option value="IE">Ireland · EUR</option><option value="SE">Sweden · SEK</option><option value="DK">Denmark · DKK</option><option value="NO">Norway · NOK</option><option value="FI">Finland · EUR</option><option value="IS">Iceland · ISK</option></select><button class="button" id="saveRegion">{t('Save preference','保存偏好')}{icon('arrow')}</button><p id="regionStatus" role="status"></p></dialog>
<div class="toast" id="toast" role="status"></div><noscript><p class="noscript">Browse the collection links above. Language switching, search and the bag need JavaScript. No orders are accepted yet.</p></noscript></body></html>'''

home=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow">{t('NOVA WELL / A NEW PERSPECTIVE','NOVA WELL／全新视角')}</p><h1>{t('A quiet statement.','不喧哗，')}<br>{t('Every day.','自有光芒。')}</h1><p class="hero-intro">{t('Jewellery. Considered forms. A little more of you, in the everyday.','时尚首饰，简洁而有分寸。为每一天，添一份自己的表达。')}</p>{button('/collections/jewellery/','Explore the collection','探索首饰系列')}<span class="hero-status">{t('Explore our jewellery catalogue','探索首饰商品目录')}</span></div><figure class="hero-visual"><img src="/assets/brand/jewellery-study.webp" alt="Original concept still life of metal jewellery on pale stone; not a product photograph" data-alt-en="Original concept still life of metal jewellery on pale stone; not a product photograph" data-alt-zh="石材上的金属首饰原创氛围图，并非待售商品实拍" width="1536" height="1024" fetchpriority="high"><figcaption>{t('Original brand imagery · Not a product listing','原创品牌氛围图 · 非待售商品')}</figcaption></figure></section>
<section class="category-section wrap" id="collections"><div class="section-heading"><div><p class="eyebrow">{t('THE JEWELLERY EDIT','首饰系列')}</p><h2>{t('Find your form.','找到你的表达。')}</h2></div><a class="text-link" href="/collections/jewellery/">{t('All jewellery','全部首饰')}{icon('arrow')}</a></div><div class="category-grid">{''.join(f'<a class="category-card" href="/collections/{slug}/"><span class="category-number">0{i+1}</span><h3>{t(en,zh)}</h3><span class="category-line" aria-hidden="true"></span>{icon("arrow")}</a>' for i,(slug,en,zh) in enumerate(CATEGORIES))}</div></section>
<section class="collection-preview wrap"><div class="preview-caption"><p class="eyebrow">{t('THE FIRST COLLECTION','首个系列')}</p><h2>{t('Something considered','用心之选，')}<br>{t('is taking shape.','即将成形。')}</h2><a class="text-link" href="/pages/about/">{t('Our perspective','品牌理念')}{icon('arrow')}</a></div><div class="collection-empty"><span class="empty-mark" aria-hidden="true">N / W</span><p class="eyebrow">{t('COLLECTION IN PREPARATION','系列筹备中')}</p><h3>{t('The details come first.','细节，先于呈现。')}</h3><p>{t('Our jewellery will appear here once the imagery, materials and measurements have been confirmed. Until then, explore the forms our collection will take.','待图片、材质及尺寸核实后，商品将在这里呈现。在此之前，欢迎先了解我们的首饰分类。')}</p>{button('/collections/jewellery/','View jewellery categories','查看首饰分类',True)}</div></section>
<section class="perspective wrap"><p class="eyebrow">{t('LESS, WITH INTENTION','简而有意')}</p><h2>{t('Not just an occasion.','不只为某个时刻，')}<br>{t('A part of your everyday.','也为你的每一天。')}</h2><div><p>{t('A necklace close to the collarbone. A bracelet that moves with you. Shapes that feel personal, without saying too much. NOVA WELL is building a jewellery collection around everyday expression.','贴近锁骨的项链，随动作轻晃的手链。简洁的形态，也能表达自己。NOVA WELL 正在围绕日常表达，筹备一个纯粹的首饰系列。')}</p><a class="text-link" href="/pages/materials-care/">{t('Materials & care','材质与护理')}{icon('arrow')}</a></div></section>'''
write('index.html',shell('Jewellery for everyday expression','首饰，为日常表达',home,'home'))

for slug,en,zh in [('jewellery','Jewellery','首饰')]+CATEGORIES:
    body=f'''<div class="wrap collection-page"><div class="breadcrumbs"><a href="/">{t('Home','首页')}</a><span>/</span>{t(en,zh)}</div><div class="collection-heading"><p class="eyebrow">NOVA WELL / {t('THE COLLECTION','首饰系列')}</p><h1>{t(en,zh)}</h1><p>{t('Considered forms for everyday expression.','简洁形态，融入日常表达。')}</p></div><nav class="collection-tabs" aria-label="Jewellery categories">{nav(slug)}</nav><div class="collection-meta"><span>{t('0 pieces','0 件商品')}</span><span>{t('Collection in preparation','系列筹备中')}</span></div><div class="collection-empty collection-large"><span class="empty-mark" aria-hidden="true">N / W</span><h2>{t('A new collection is taking shape.','全新系列，正在成形。')}</h2><p>{t('There are no products in this category yet. Verified product photographs, materials and options will appear with our first release.','此分类暂未上架商品。经核实的商品照片、材质及规格选项，将随首批系列一同呈现。')}</p>{button('/pages/about/','Discover our perspective','了解品牌理念',True)}</div></div>'''
    write(f'collections/{slug}/index.html',shell(en,zh,body,'collection',slug))

search=f'''<div class="prose wrap"><div class="breadcrumbs"><a href="/">{t('Home','首页')}</a><span>/</span>{t('Search','搜索')}</div><p class="eyebrow">{t('THE JEWELLERY EDIT','首饰系列')}</p><h1>{t('Find your everyday piece.','寻找你的日常首饰。')}</h1><form class="search-form" data-search-form data-search-page><label for="pageSearch">{t('Search jewellery','搜索首饰')}</label><div class="search-input-row"><input id="pageSearch" name="q" type="search" maxlength="120" placeholder="Necklaces, rings, everyday details…"><button class="icon-button" type="submit" aria-label="Search">{icon('search')}</button></div></form><p class="search-count" role="status">{t('0 results · Collection in preparation','0 条结果 · 系列筹备中')}</p><section class="search-empty-page"><h2>{t('The collection is still taking shape.','首饰系列，仍在筹备。')}</h2><p>{t('There are no products to search yet. You can explore our five jewellery categories below.','目前暂无可搜索商品，你可以先浏览下方五个首饰分类。')}</p><nav class="text-categories" aria-label="Jewellery categories">{nav()}</nav></section></div>'''
write('pages/search/index.html',shell('Search jewellery','搜索首饰',search,'search'))

info={
'about':('Our perspective','品牌理念',[("Considered forms. Everyday expression.",'简洁形态，日常表达。',"NOVA WELL is creating a jewellery-only edit of necklaces, bracelets, rings, earrings and pendants. Our focus is on shapes and details that feel at home in everyday life.",'NOVA WELL 专注于项链、手链、戒指、耳环及吊坠，以贴近日常的形态与细节，呈现首饰的表达。'),('A collection in the making.','首饰系列筹备中。','Our first products will be introduced after their photographs, materials, dimensions and available options have been verified. The brand imagery is an original concept study, not a representation of products currently for sale.','首批商品将在照片、材质、尺寸及可选规格核实后介绍。品牌氛围图为原创概念视觉，不代表当前在售商品。')]),
'materials-care':('Materials & care','材质与护理',[('The details of each piece.','每件首饰，都有自己的细节。','Our focus is stainless-steel fashion jewellery. Exact steel grade, finish, plating, colour and any additional materials will be stated for each verified product. A gold-colour or silver-colour appearance does not by itself identify the metal composition.','我们以不锈钢时尚首饰为主营方向。具体钢材牌号、表面工艺、镀层、颜色及其他材质，将按每款商品的核实资料说明。金色或银色外观本身并不代表金属成分。'),('Care, specific to your jewellery.','护理，需对应具体商品。','Care instructions will accompany each product once confirmed. We have not yet made product-level claims about water resistance, allergy suitability, plating life or precious-metal content.','护理说明将在确认后随具体商品提供。目前尚未作出防水、过敏适用性、镀层寿命或贵金属含量等商品级承诺。')]),
'size-guide':('Size guide','尺寸指南',[('Find the right dimensions.','了解适合自己的尺寸。','Verified dimensions and measuring guidance will be provided with each product. Ring sizes, chain lengths, extension lengths, pendant measurements and bracelet lengths will use the supplier information confirmed for that item.','每款商品将提供经核实的尺寸及测量说明。戒指尺码、链长、延长链、吊坠尺寸和手链长度，均以对应商品确认后的资料为准。'),('Options that match the piece.','选项，匹配实际商品。','Gold-colour and silver-colour choices, ring sizes, chain lengths, and single or paired earrings will only be offered where that product actually supports them. Pendants will state clearly whether a chain is included.','仅在商品实际支持时，提供金／银色、戒指尺码、链长及耳饰单只／成对选项。吊坠是否含链条，将明确说明。')]),
'shipping':('Shipping & delivery','配送说明',[('Our planned regions.','计划服务地区。','We are preparing for the United Kingdom, Ireland, Sweden, Denmark, Norway, Finland and Iceland. Browsing a region does not yet confirm that delivery is available there.','我们正在面向英国、爱尔兰、瑞典、丹麦、挪威、芬兰及冰岛筹备。选择浏览地区，暂不代表该地区已经支持配送。'),('Before ordering opens.','开放订单之前。','Dispatch location, delivery services, times, fees and destination charges are still to be confirmed. Applicable delivery options and the final total will be shown before a real purchase can be made.','发货地、配送服务、时效、费用及目的地相关费用仍待确认。实际购买前将展示适用配送选项与最终金额。')]),
'returns':('Returns','退货说明',[('A clear process, before you purchase.','购买前，先明确流程。','Our return arrangements are being prepared. The return location, steps, postage responsibilities and refund process will be published before orders open.','退货安排正在筹备中。开放订单前将公布退货地点、步骤、邮费责任及退款流程。'),('Specific to your order.','对应你的商品与订单。','Any product-specific conditions will be explained before purchase. There are no orders or returns to process during this collection preparation stage.','与商品相关的具体条件将在购买前说明。系列筹备期间，本站暂不处理实际订单或退货。')]),
'contact':('Contact','联系我们',[('We are preparing to welcome you.','期待与你相遇。','Our verified customer-care contact and response hours will be published before the collection opens for orders. No contact form or personal information is collected on this page.','经核实的客服联系方式及服务时间，将在开放订单前公布。本页不设置联系表单，也不收集个人信息。')]),
'order-status':('Order status','订单查询',[('Ordering has not opened yet.','订单尚未开放。','There are no orders to look up yet. Guest order lookup will be introduced with the purchasing service, using a secure verification process.','目前暂无可查询订单。游客订单查询将在购买服务开放时接入，并采用安全验证流程。')]),
'updates':('Collection updates','系列动态',[('The first release is on its way.','首个系列，正在筹备。','Future collection updates will be available here. Email subscriptions will open once our sending and unsubscribe service is connected. No email addresses are being collected yet.','后续系列动态将在这里公布。邮件订阅将在发信及退订服务接通后开放，目前暂不收集邮箱地址。')]),
'privacy':('Privacy','隐私说明',[('Your browsing preferences.','你的浏览偏好。','This site stores your language and browsing region on this device. Retired catalogue bag records and legacy editor drafts are removed when the jewellery-only site is first opened. We do not collect customer names, email addresses, delivery details or payment information during this preparation stage.','本站在本设备保存语言及浏览地区偏好。首次打开纯首饰新版时，会清理旧目录购物袋记录及旧编辑器草稿。筹备阶段不收集客户姓名、邮箱、收货详情或支付信息。'),('Your choices.','你的选择。','You can clear this site’s saved preferences below. A complete privacy notice for purchasing and subscriptions will be provided before those services are enabled. Hosting services may retain normal request logs.','你可以通过下方按钮清除本站保存的偏好。购买及订阅服务启用前，将提供完整隐私说明。托管服务商可能保留常规请求日志。')]),
'terms':('Terms','使用条款',[('A collection in preparation.','系列筹备中。','This site currently introduces the NOVA WELL jewellery brand and its planned categories. Product information is provided as a catalogue preview; retail prices and availability are not confirmed, and no orders or payments are accepted. The editorial image is an original AI-generated brand concept, not a sale offer.','本站目前用于介绍 NOVA WELL 首饰品牌及计划分类，商品资料以目录预览形式展示，零售价及供货状态尚未确认，暂不接受订单或付款。品牌氛围图为 AI 原创概念视觉，不构成销售报价。'),('Before commercial launch.','正式营业之前。','Verified product details, seller information, pricing, delivery, returns and applicable purchasing terms will be provided before real orders are enabled.','真实订单启用前，将补齐经核实的商品详情、经营者信息、售价、配送、退货及适用购买条款。')])}
